import { Search, type SearchProps } from "@components/search";
import { clsx } from "clsx";

import { useList } from "../hooks/use-list";
import { ListClasses } from "../list.styles";

export const ListSearch = ({
  className,
  onQueryChange,
  value,
  children,
  "aria-label": ariaLabel = "Search list",
  ...props
}: SearchProps) => {
  const list = useList();
  const globalFilter = list.getState().globalFilter;

  return (
    <Search
      className={clsx(ListClasses.searchInput, className)}
      openOnClick={false}
      {...props}
      value={value !== undefined ? value : globalFilter || ""}
      onQueryChange={(query: SearchProps["query"]) => {
        list.setGlobalFilter(query);
        onQueryChange?.(query);
      }}
    >
      {children || (
        <Search.Input aria-label={ariaLabel}>
          <Search.InputPrefix />
          <Search.InputSuffix>
            <Search.ClearIconButton />
          </Search.InputSuffix>
        </Search.Input>
      )}
    </Search>
  );
};

ListSearch.displayName = "List.Search";
